import React from "react";
import clsx from "clsx";
import { createUseStyles } from "../../lib/styling";
import { FlexLayout, FlexLayoutProps } from "../internal/FlexLayout";
import {
  AlignItems,
  AlignItemsValues,
  Spacing,
  SpacingValues,
} from "../helperTypes";
import { spacingToTokenValue } from "../../lib/utils";

export type StackProps = {
  /** Aligns children horizontally */
  align?: AlignItems;
  /** Specifies the gap beween children */
  spacing?: Spacing;
} & FlexLayoutProps;

const useStyles = createUseStyles(
  () => {
    const alignItemsClasses: any = {};
    AlignItemsValues.forEach((align) => {
      alignItemsClasses[`align-${align}`] = {
        alignItems: align === "center" ? align : `flex-${align}`,
      };
    });

    const spacingClasses: any = {};
    SpacingValues.forEach((spacing) => {
      spacingClasses[`child--spacing-${spacing}`] = {
        marginBottom: spacingToTokenValue(spacing),
      };
    });

    return {
      root: {
        display: "flex",
        flexDirection: "column",
      },
      child: {
        marginTop: 0,
        "&:last-child": {
          marginBottom: 0,
        },
      },
      ...alignItemsClasses,
      ...spacingClasses,
    };
  },
  "stack"
);

const Stack = ({
  className,
  childrenClassName,
  spacing,
  align,
  ...rest
}: StackProps) => {
  const classes = useStyles({ spacing, align });
  return (
    <FlexLayout
      className={clsx(
        className,
        classes.root,
        align && classes[`align-${align}`]
      )}
      childrenClassName={clsx(
        classes.child,
        childrenClassName,
        spacing && classes[`child--spacing-${spacing}`]
      )}
      {...rest}
    />
  );
};

export default Stack;
